[85]={class=[[LocalScript]],source=[[local ts = game:GetService("TweenService")
local ti = TweenInfo.new(0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
local display = script.Parent.Parent.display

local rs = game:GetService("ReplicatedStorage")
local Remotes = rs:WaitForChild("Remotes")
local Emote = Remotes:WaitForChild("Emote")
local g

local offPos = UDim2.new(0.5,0,1.3,0)
local onPos = UDim2.new(0.5,0,0.6,0)
local onSFX = script:WaitForChild("onSFX")
local offSFX = script:WaitForChild("offSFX")

local v = false
local debounce = false

local plr = game.Players.LocalPlayer
local char = plr.Character or plr.CharacterAdded:Wait()

script.Parent.ImageButton.Activated:Connect(function()
	if debounce then return end
	
	debounce = true
	if not v then
		local t = ts:Create(display, ti, {Position = onPos}):Play()
		onSFX:Play()
	else
		local t = ts:Create(display, ti, {Position = offPos}):Play()
		offSFX:Play()
	end
	v = not v
	wait(1)
	debounce = false
end)

for _,v in script.Parent.Parent.display:GetDescendants() do
	if v:IsA("TextButton") then
		v.Activated:Connect(function()
			if char:FindFirstChild("qbfd8b3bf7ac864d9") then
				if char.stun:IsA("BoolValue") then
					return
				end
			end
			if char:FindFirstChild("q811f2132e7542a42") then
				if char.carrying:IsA("BoolValue") then
					return
				end
			end
			if char:GetAttribute("q9e5fe3c6a1262529") == true then
				return 
			end
			Emote:FireServer(v.Name)
		end)
	end
end

local vertTi = TweenInfo.new(1.3, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true)
local horTi = TweenInfo.new(1.3, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true)
local vertT = ts:Create(script.Parent, vertTi, {Position = UDim2.new(0,30,0,10)})
local horT = ts:Create(script.Parent, horTi, {Rotation = -2})

vertT:Play()
wait(0.4)
horT:Play()]]},
[136]={class=[[LocalScript]],source=[[local rs = game:GetService("ReplicatedStorage")
local ts = game:GetService('TweenService')
local Remotes = rs:WaitForChild("Remotes")
local AwakenScreen = Remotes:WaitForChild("AwakenScreen")

local ti = TweenInfo.new(0.1, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
local ti2 = TweenInfo.new(0.3, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
local ti2 = TweenInfo.new(0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)

AwakenScreen.OnClientEvent:Connect(function()
	local light = script.ColorCorrection:Clone()
	light.Parent = game.Lighting
	
	game.Debris:AddItem(light, 0.5)
	
	task.spawn(function()
		for _,v in script.Parent:GetDescendants() do
			if v:IsA("ImageLabel") then
				v.Visible = true
				v.ImageTransparency = 0
				local y = ts:Create(v, ti2, {ImageTransparency = 1}):Play()
			end
		end
		wait(0.5)
		for _,v in script.Parent:GetDescendants() do
			if v:IsA("ImageLabel") then
				v.Visible = false
			end
		end
	end)
	
	local t = ts:Create(light, ti, {Brightness = 0.5}):Play()
	local t2 = ts:Create(light, ti, {Contrast = 1}):Play()
	local t3 = ts:Create(light, ti, {Saturation = 1}):Play()
	local t4 = ts:Create(light, ti, {TintColor = Color3.fromRGB(255,20,29)})
	t4:Play()
	t4.Completed:Wait()
	wait(.7)
	local t5 = ts:Create(light, ti2, {Brightness = 0}):Play()
	local t6 = ts:Create(light, ti2, {Contrast = 0}):Play()
	local t7 = ts:Create(light, ti2, {Saturation = 0}):Play()
	local t8 = ts:Create(light, ti2, {TintColor = Color3.fromRGB(255,255,255)})
	t8:Play()
	
end)]]},
[164]={class=[[LocalScript]],source=[[local debrisService = game:GetService("Debris")
local tweenService = game:GetService("TweenService")
local enabledButton = nil
local replicatedStorage = game:GetService("ReplicatedStorage")
local setInfoEvent = replicatedStorage.AttributeSystem.SetInfo
local players = game:GetService("Players")
local player = players.LocalPlayer

for _, button in pairs(script.Parent:GetChildren()) do
	if not button:IsA("TextButton") then continue end
	
	
	
	button.MouseEnter:Connect(function()
		local hoverSoundClone = script.Hover:Clone()
		hoverSoundClone.Parent = workspace.CurrentCamera
		hoverSoundClone:Play()
		debrisService:AddItem(hoverSoundClone, hoverSoundClone.TimeLength)

		if tonumber(button.Name) then
			tweenService:Create(button, TweenInfo.new(0.1, Enum.EasingStyle.Linear, Enum.EasingDirection.In), {
				BackgroundColor3 = Color3.fromRGB(72, 0, 130)
			}):Play()
		end

		if button.Name ~= "Close" then
			tweenService:Create(button, TweenInfo.new(0.1, Enum.EasingStyle.Linear, Enum.EasingDirection.In), {
				Rotation = -3
			}):Play()
		end
	end)

	button.MouseLeave:Connect(function()
		if tonumber(button.Name) and enabledButton ~= button then
			tweenService:Create(button, TweenInfo.new(0.1, Enum.EasingStyle.Linear, Enum.EasingDirection.In), {
				BackgroundColor3 = Color3.fromRGB(72, 0, 130)
			}):Play()
		end

		if button.Name ~= "Close" and enabledButton ~= button then
			tweenService:Create(button, TweenInfo.new(0.1, Enum.EasingStyle.Linear, Enum.EasingDirection.In), {
				Rotation = 0
			}):Play()
		end
	end)

	button.MouseButton1Click:Connect(function()
		
		local clickSoundClone = script.Click:Clone()
		clickSoundClone.Parent = workspace.CurrentCamera
		clickSoundClone:Play()
		debrisService:AddItem(clickSoundClone, clickSoundClone.TimeLength)

		if not tonumber(button.Name) then 
			setInfoEvent:FireServer("qe8be68a176690a76", button.Text)
		end
		
		wait(.1) -- allow properties to be set, task.defer is too fast.
		
		if player:GetAttribute("qe8be68a176690a76") then
			script.Parent.Parent.Enabled = false 
			--player.PlayerGui:WaitForChild("main").Enabled = true
			
		end
	end)
end]]},
