[278]={class=[[Script]],source=[[local ts = game:GetService("TweenService")
local setMotor6D = script.Parent:WaitForChild("SetMotor6D")
local DashEvent = script.Parent:WaitForChild("Dash")

local rs = game:GetService("ReplicatedStorage")
local VFX = rs:WaitForChild("VFX")
local dashLimbs = VFX:WaitForChild("dash_limbs")
local dashSmoke = VFX:WaitForChild("dash_smoke")

local CombatFunctions = require(rs:WaitForChild("CombatFunctions"))

setMotor6D.OnServerEvent:Connect(function(plr, t)
	local char = plr.Character
	
	local prevWeld = char:FindFirstChild("Right Arm"):WaitForChild("RightGrip")
	
	if t then
		local newWeld = Instance.new("Motor6D")
		newWeld.Parent = char:FindFirstChild("Right Arm")
		newWeld.Name = "RightGrip"
		newWeld.Part0 = prevWeld.Part0
		newWeld.Part1 = prevWeld.Part1

		newWeld.C0 = prevWeld.C0
		newWeld.C1 = prevWeld.C1
		prevWeld:Destroy()
	else
		prevWeld:Destroy()
	end

end)

DashEvent.OnServerEvent:Connect(function(plr, inAir, awakened)
	local char = plr.Character
	
	local h = Instance.new("Highlight")
	h.DepthMode = Enum.HighlightDepthMode.Occluded
	
	if awakened then
		h.FillColor = Color3.fromRGB(255,0,0)
		h.OutlineColor = Color3.fromRGB(255,0,0)
		CombatFunctions:playSound(script.awakened, char.HumanoidRootPart)
	else
		h.FillColor = Color3.fromRGB(255,255,255)
		h.OutlineColor = Color3.fromRGB(255,255,255)
		CombatFunctions:playSound(script.normal, char.HumanoidRootPart)
	end
	
	h.FillTransparency = 0.7
	h.OutlineTransparency = 0
	h.Parent = char

	local ti = TweenInfo.new(0.4, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
	local t = ts:Create(h, ti, {OutlineTransparency = 1})
	t:Play()
	game.Debris:AddItem(h, 0.4)
	
	local limbs = {"Left Arm", "Right Arm", "Right Leg", "Left Leg"}
	local enabled_trails = {}
	for _,l in limbs do
		-- random ahh check
		if char[l]:FindFirstChild("dash0") then
			for _,thing in char[l]:GetChildren() do
				if thing:IsA("Trail") and string.find(thing.Name, "dash") then
					thing.Enabled = true
					table.insert(enabled_trails, thing)
				end
			end
		else
			local dash_vfx = dashLimbs:Clone():GetChildren()
			for _,p in dash_vfx do
				p.Parent = char[l]
				if p:IsA("Trail") then
					p.Enabled = true
					table.insert(enabled_trails, p)
				end
			end
		end
	end

	task.spawn(function()
		task.wait(0.3)
		for _,e in enabled_trails do
			e.Enabled = false
		end
	end)

	if not inAir then
		if not char.PrimaryPart:FindFirstChild("dust") then
			local smoke = dashSmoke.dust:Clone()
			smoke.Parent = char.PrimaryPart
		end
		for _,part in char.PrimaryPart.dust:GetChildren() do
			part.Enabled = true
		end
		task.spawn(function()
			task.wait(0.3)
			for _,part in char.PrimaryPart.dust:GetChildren() do
				part.Enabled = false
			end
		end)
	end
end)]]},
[281]={class=[[LocalScript]],source=[[
local function __rtSound(sound,start,duration,speed)
    if not sound then return end
    local c=sound:Clone(); c.Parent=sound.Parent
    if start then c.TimePosition=start end; if speed then c.PlaybackSpeed=speed end
    c:Play(); game:GetService("Debris"):AddItem(c,duration or 12)
end
local function __rtParticles(p,t,d)
    local a=typeof(p)=="table" and p or {p}
    for _,x in ipairs(a) do if x then pcall(function()x.Enabled=t end) end end
    if d then task.delay(d,function() for _,x in ipairs(a) do if x then pcall(function()x.Enabled=false end) end end end) end
end
local function __rtFlash(fill,outline,duration)
    local c=game:GetService("Players").LocalPlayer.Character; if not c then return end
    local h=Instance.new("Highlight");h.FillColor=fill;h.OutlineColor=outline;h.FillTransparency=.2;h.Parent=c
    game:GetService("TweenService"):Create(h,TweenInfo.new(duration or .4),{FillTransparency=1,OutlineTransparency=1}):Play()
    game:GetService("Debris"):AddItem(h,duration or .4)
end
--Made by Luckymaxer

Mouse_Icon = "rbxasset://textures/GunCursor.png"
Reloading_Icon = "rbxasset://textures/GunWaitCursor.png"

Tool = script.Parent

local char = game.Workspace:WaitForChild(game.Players.LocalPlayer.Name)
local hum = char:WaitForChild("Humanoid")
local root = char.HumanoidRootPart

local rs = game:GetService("ReplicatedStorage")
local uis = game:GetService("UserInputService")
local flourish_anim = rs.Animations.bat.flourish
local unequip = rs.Animations.bat.unequip

local m1_count = 1

local currentPlaying
localAnimationPlayer = require(game:GetService("ReplicatedStorage"):WaitForChild("AnimationManager"))

local Hitboxes = require(script:WaitForChild("Hitboxes"))
local MoveData = require(rs:WaitForChild("MoveData"))
local CombatFunctions = require(rs:WaitForChild("CombatFunctions"))

local Rate = 1 / 60 -- 10 times a second
local swing_debounce = true
local dash_debounce = false
local Accumulated = 0
local RunService = game:GetService"RunService"
local Heartbeat = RunService.Heartbeat

local rs = game:GetService("ReplicatedStorage")
local Remotes = rs:WaitForChild("Remotes")
local PlaySound = Remotes:WaitForChild("PlaySound")
local DashEvent = script.Parent:WaitForChild("Dash")
local ToggleParticles = Remotes:WaitForChild("ToggleParticles")
local Flash = Remotes:WaitForChild("Flash")
local ChangeAttacking = Remotes:WaitForChild("ChangeAttacking")

local Toggle = game.Players.LocalPlayer.PlayerGui.HitboxToggle:WaitForChild("Toggle")

hitbox_list = {}

local setMotor6D = Tool:WaitForChild("SetMotor6D")

local swingSound = Tool.Handle:WaitForChild("Swing")
local equip = Tool.Handle:WaitForChild("Equip")
local equip2 = Tool.Handle:WaitForChild("Equip2")
local unequipSound = Tool.Handle:WaitForChild("Unequip")

local inputConnection
local mobileDashConnection

local mobileButtons = game.Players.LocalPlayer.PlayerGui:WaitForChild("mobileButtons")
local DashButton = mobileButtons.Dash

local prevAttacking = false

Heartbeat:Connect(function(DeltaTime)
	Accumulated += DeltaTime
	while Accumulated >= Rate do
		Accumulated -= Rate
		local canAttack = true
		if char:FindFirstChild("qbfd8b3bf7ac864d9") then
			if char.stun:IsA("BoolValue") then
				canAttack = false
			end
		end
		if char:FindFirstChild("q811f2132e7542a42") then
			if char.carrying:IsA("BoolValue") then
				canAttack = false
			end
		end
		if char:GetAttribute("q9e5fe3c6a1262529") == true then
			canAttack = false
		end
		if canAttack then
			for _,hitbox in pairs(hitbox_list) do
				local check = hitbox:updateFrame()
				hitbox:activate()
				if Toggle.Value then
					hitbox:draw()
				end
				if check == true then
					table.remove(hitbox_list, table.find(hitbox_list, hitbox))
				end
			end
			if #hitbox_list > 0 then
				if not prevAttacking then
					prevAttacking = true
					ChangeAttacking:FireServer(true)
				end
			else
				if prevAttacking then
					prevAttacking = false
					ChangeAttacking:FireServer(false)
				end
			end
		else
			if prevAttacking then
				prevAttacking = false
				ChangeAttacking:FireServer(false)
			end
			hitbox_list = {}
		end
	end
end)

Mouse = nil

function UpdateIcon()
	if Mouse then
		Mouse.Icon = Tool.Enabled and Mouse_Icon or Reloading_Icon
	end
end

function Swing()
	if char:FindFirstChild("qbfd8b3bf7ac864d9") then
		if char.stun:IsA("BoolValue") then
			warn("is stunned - cannot attack")
			return
		end
	end
	if char:FindFirstChild("q811f2132e7542a42") then
		if char.carrying:IsA("BoolValue") then
			warn("is carrying - cannot attack")
			return
		end
	end
	if char:GetAttribute("q9e5fe3c6a1262529") == true then
		return 
	end
	if swing_debounce == false then
		swing_debounce = true
		localAnimationPlayer.PlayAnimation(rs.Animations.bat["swing_"..m1_count], game.Players.LocalPlayer.Character)
		
		if m1_count ~= 3 then
			table.insert(hitbox_list, Hitboxes.new(game.Players.LocalPlayer, MoveData.get_data("SWING_"..m1_count)))
			__rtSound(swingSound, nil, nil, ((math.random(-50, 50) * 0.01) + 1))
			__rtParticles(Tool.Handle.Trail, true, 0.5)
			m1_count += 1
		else
			table.insert(hitbox_list, Hitboxes.new(game.Players.LocalPlayer, MoveData.get_data("qa2db6280bcedf828")))
			__rtFlash(Color3.fromRGB(227, 219, 219), Color3.fromRGB(0, 0, 0), 0.4)
			wait(0.7)
			__rtSound(swingSound, nil, nil, ((math.random(-50, 50) * 0.01) + 1))
			__rtParticles(Tool.Handle.Trail, true, 0.5)
			m1_count = 1
		end
		
		wait(0.4)
		swing_debounce = false
	end
end

function Dash()
	if char:FindFirstChild("qbfd8b3bf7ac864d9") then
		if char.stun:IsA("BoolValue") then
			warn("is stunned - cannot dash")
			return
		end
	end
	if char:FindFirstChild("q811f2132e7542a42") then
		if char.carrying:IsA("BoolValue") then
			warn("is carrying - cannot dash")
			return
		end
	end
	if char:GetAttribute("q9e5fe3c6a1262529") == true then
		return 
	end
	if dash_debounce == false  then
		dash_debounce = true

		__rtSound(script.Parent.Handle:FindFirstChild("DashSound"), nil, nil)
		hum.JumpPower = 0
		
		local DASH_DISTANCE = 18
		
		if char:GetAttribute("qc8dcddf8633621bd") then
			DASH_DISTANCE = 25
		else
			DASH_DISTANCE = 18
		end
		
		--if hum.FloorMaterial ~= Enum.Material.Air then
		--	ReplicationEvent:FireServer("Dash", true)
		--else
		--	ReplicationEvent:FireServer("Dash", false)
		--end

		--local DASH_DISTANCE = nil
		--if Items.GetItemInfo(DataDirectory[plr.Name].Style.Value, "DashDistance") == nil then
		--	print("default dash")
		--	DASH_DISTANCE = Items.GetItemInfo("Combat", "DashDistance")
		--else
		--	DASH_DISTANCE = Items.GetItemInfo(DataDirectory[plr.Name].Style.Value, "DashDistance")
		--	if DataDirectory[plr.Name].Style.Value == "Rush" then
		--		AttackEvent:FireServer("SkillRep", "Rush", "Dash")
		--	end
		--end
		
		if hum.FloorMaterial == Enum.Material.Air then
			DashEvent:FireServer(true, char:GetAttribute("qc8dcddf8633621bd"))
		else
			DashEvent:FireServer(false, char:GetAttribute("qc8dcddf8633621bd"))
		end

		local dir_cframe 
		local velocity = root.CFrame:Inverse() * (root.Position + root.Velocity)
		local yDirection = math.atan2(velocity.X, -velocity.Z)
		local roundedDirection = math.ceil(math.deg(yDirection) - 0.5)	

		if (roundedDirection <= -135 or roundedDirection >= 135) then
			-- DASH BACK
			dir_cframe = CFrame.new(0,0,DASH_DISTANCE)
		elseif roundedDirection < -45 and roundedDirection > -135 then
			-- DASH LEFT
			dir_cframe = CFrame.new(-DASH_DISTANCE,0,0)
		elseif roundedDirection > 45 and roundedDirection < 135 then
			-- DASH RIGHT
			dir_cframe = CFrame.new(DASH_DISTANCE,0,0)
		elseif roundedDirection <= 45 and roundedDirection >= -45 then
			-- DASH FORWARD
			dir_cframe = CFrame.new(0,0,-DASH_DISTANCE)
		end

		wait(0.15)
		
		CombatFunctions:pull(root, dir_cframe, 0.3, 30000, 30, "dash_part")
		
		wait(0.7)

		hum.JumpPower = 50
		
		wait(0.5)
		
		dash_debounce = false
	end
end

function OnEquipped(ToolMouse)
	swing_debounce = true
	Mouse = ToolMouse
	UpdateIcon()
	setMotor6D:FireServer(true)
	__rtSound(equip, nil, nil)
	localAnimationPlayer.PlayAnimation(flourish_anim, game.Players.LocalPlayer.Character)
	wait(1.5)
	__rtSound(equip2, nil, nil)
	wait(0.25)
	
	swing_debounce = false

	inputConnection = uis.InputBegan:Connect(function(input, gp)
		if gp then return end
		if input.KeyCode == Enum.KeyCode.Q then
			Dash()
		end
	end)
	
	mobileDashConnection = DashButton.Activated:Connect(function(input, clickNumber)
		Dash()
	end)
	--local prevWeld = char:FindFirstChild("Right Arm"):WaitForChild("RightGrip")
	--local newWeld = Instance.new("Motor6D")
	--newWeld.Parent = char:FindFirstChild("Right Arm")
	--newWeld.Name = "RightGrip"
	--newWeld.Part0 = prevWeld.Part0
	--newWeld.Part1 = prevWeld.Part1

	--newWeld.C0 = prevWeld.C0
	--newWeld.C1 = prevWeld.C1
	--prevWeld:Destroy()
end


function OnChanged(Property)
	if Property == "Enabled" then
		UpdateIcon()
	end
end

function onUnequip()
	if inputConnection then
		inputConnection:Disconnect()
	end
	if mobileDashConnection then
		mobileDashConnection:Disconnect()
	end
	
	prevAttacking = false
	ChangeAttacking:FireServer(false)
	
	localAnimationPlayer.PlayAnimation(unequip, game.Players.LocalPlayer.Character)
	__rtSound(unequipSound)
	setMotor6D:FireServer(false)
end

Tool.Equipped:Connect(OnEquipped)
Tool.Changed:Connect(OnChanged)
Tool.Activated:Connect(Swing)
Tool.Unequipped:Connect(onUnequip)

]]},
[283]={class=[[ModuleScript]],source=[[local Hitboxes = {}

Hitboxes.__index = Hitboxes

-- SERVICES
local debris = game:GetService("Debris")
local Remotes = game.ReplicatedStorage.Remotes
local hit = Remotes:WaitForChild("Hit")
local HitCount = require(game.Players.LocalPlayer.PlayerScripts:WaitForChild("HitCount"))

function Hitboxes.new(player, move_data)
	local hb = {}
	
	hb.owner_char = player.Character
	hb.ignore_characters = {hb.owner_char}
	
	hb.region = {hb.owner_char.HumanoidRootPart.CFrame * move_data["q64f23cca3554c22c"], move_data["qbffe97c74aaef824"]}
	hb.move_data = move_data
	hb.ended = false
	hb.current_state = "qd980330884814903"
	hb.current_frame = 1

	setmetatable(hb, Hitboxes)
	return hb
end

function Hitboxes:updateFrame()
	if self.ended == false then
		if self.move_data["qd980330884814903"] <= self.current_frame then
			self.current_state = "qd89ad37a75e97a0f"
		end
		if self.move_data["qd980330884814903"] + self.move_data["qd89ad37a75e97a0f"] <= self.current_frame then
			self.ended = true
			self.current_state = "recovery"
		end
		self.current_frame += 1
	end
	
	self.region = {self.owner_char.HumanoidRootPart.CFrame * self.move_data["q64f23cca3554c22c"], self.move_data["qbffe97c74aaef824"]}
	
	self.ignore_list = self.owner_char:GetDescendants()
	for index,child in pairs(self.ignore_list) do
		if child:IsA("BasePart") == false then
			table.remove(self.ignore_list,index)
		end
	end
	
	return self.ended
end

function Hitboxes:draw()
	local hitbox_ref = Instance.new("Part")
	local hitbox_outline = Instance.new("SelectionBox")
	hitbox_ref.Transparency = 0.95
	hitbox_ref.Material = Enum.Material.SmoothPlastic
	hitbox_ref.Size = self.region[2]
	hitbox_ref.CFrame = self.region[1]
	hitbox_ref.CanCollide = false
	hitbox_ref.Anchored = true
	hitbox_ref.Name = "hitbox_ref"
	hitbox_outline.Adornee = hitbox_ref
	hitbox_outline.LineThickness = 0.03
	hitbox_outline.Parent = hitbox_ref
	if self.current_state == "qd89ad37a75e97a0f" then
		hitbox_outline.Color3 = Color3.fromRGB(0,255,0)
		hitbox_ref.Color = Color3.fromRGB(0,255,0)
	else
		hitbox_outline.Color3 = Color3.fromRGB(255,0,0)
		hitbox_ref.Color = Color3.fromRGB(255,0,0)
	end
	hitbox_ref.Parent = game.Workspace
	debris:AddItem(hitbox_ref, 0.05)
end

function Hitboxes:destroy()
	self.ended = true
end
function Hitboxes:activate()
	if self.current_state == "qd89ad37a75e97a0f" then
		print("activated")
		local collided = workspace:GetPartBoundsInBox(self.region[1], self.region[2])
		
		for _,part in pairs(collided) do
			if table.find(self.ignore_characters, part.Parent) == nil and part.Parent ~= workspace and part.Parent:FindFirstChild("Humanoid") and part.Name ~= "hitbox_ref" and not part.Parent:GetAttribute("q53f7d245ca745c33") then
				table.insert(self.ignore_characters, part.Parent)
				print(part.Parent)
				hit:FireServer(part.Parent, self.move_data)
				HitCount(self.move_data["q413966676fb53214"])
			end
		end
	end
end

return Hitboxes]]},
